1	#!/usr/bin/env node
2	// Port of /workspace/dataset/bech32/test12.py
3	//
4	//   decoded = bech32.decode(args.a, args.b)
5	//   if decoded[0] is not None and decoded[1] is not None:
6	//       witver, witprog = decoded
7	//       converted = bech32.convertbits(witprog, 5, 8)
8	//       print(witver)
9	//       print(converted)
10	
11	import * as bech32 from './lib/bech32/index.mjs';
12	import { ArgumentParser, ParserExit } from './lib/cli/argparse.mjs';
13	import { pyRepr } from './lib/python/repr.mjs';
14	import { print, writeStderr, writeStdout } from './lib/python/stdio.mjs';
15	
16	function buildParser() {
17	  const parser = new ArgumentParser();
18	  parser.addArgument(['--a'], { type: String, required: true }); // HRP
19	  parser.addArgument(['--b'], { type: String, required: true }); // Segwit address
20	  return parser;
21	}
22	
23	function main(argv) {
24	  const parser = buildParser();
25	  const args = parser.parseArgs(argv);
26	
27	  const decoded = bech32.decode(args.a, args.b); // Decode segwit address
28	  // Python's `is not None`, not a truthiness test: witness version 0 is falsy
29	  // in JavaScript but is a perfectly good result here.
30	  if (decoded[0] !== null && decoded[1] !== null) {
31	    const [witver, witprog] = decoded;
32	    const converted = bech32.convertbits(witprog, 5, 8); // Convert 5-bit to 8-bit
33	    print(pyRepr(witver));
34	    print(pyRepr(converted));
35	  }
36	}
37	
38	try {
39	  main(process.argv.slice(2));
40	} catch (error) {
41	  if (!(error instanceof ParserExit)) {
42	    throw error;
43	  }
44	  writeStdout(error.stdout);
45	  writeStderr(error.stderr);
46	  // Setting exitCode rather than calling process.exit() lets Node flush both
47	  // streams before the process goes away.
48	  process.exitCode = error.status;
49	}
