1	// Control-flow signals used by the argparse port.
2	
3	/**
4	 * A recoverable parse failure. `ArgumentParser.parseKnownArgs` catches these and
5	 * converts them into a `parser.error(...)`, exactly as CPython's
6	 * `parse_known_args` does.
7	 *
8	 * The rendered form is `argument --a: expected one argument`, where the argument
9	 * name is every option string for the action joined by `/`.
10	 */
11	export class ArgumentError extends Error {
12	  constructor(action, detail) {
13	    super(action === null ? detail : `argument ${action.optionStrings.join('/')}: ${detail}`);
14	    this.name = 'ArgumentError';
15	  }
16	}
17	
18	/**
19	 * A request to terminate, carrying whatever the parser wanted to emit first.
20	 * `--help` exits 0 with the help text on stdout; a usage error exits 2 with the
21	 * usage line plus the message on stderr.
22	 */
23	export class ParserExit extends Error {
24	  constructor(status, { stdout = '', stderr = '' } = {}) {
25	    super(`parser exit ${status}`);
26	    this.name = 'ParserExit';
27	    this.status = status;
28	    this.stdout = stdout;
29	    this.stderr = stderr;
30	  }
31	}
32

1	// Usage and help rendering, reproducing argparse's HelpFormatter layout.
2	
3	const INDENT = 2;
4	const MAX_HELP_POSITION = 24;
5	
6	/** `-h, --help` for a flag, `--a A` for an option that takes a value. */
7	export function formatInvocation(action) {
8	  const joined = action.optionStrings.join(', ');
9	  return action.nargs === 0 ? joined : `${joined} ${action.metavar}`;
10	}
11	
12	/** The bracketed form used in the usage line, built from the first option only. */
13	function formatUsagePart(action) {
14	  const option = action.optionStrings[0];
15	  const part = action.nargs === 0 ? option : `${option} ${action.metavar}`;
16	  return action.required ? part : `[${part}]`;
17	}
18	
19	export function formatUsage(prog, actions) {
20	  const parts = actions.map(formatUsagePart);
21	  const tail = parts.length === 0 ? '' : ` ${parts.join(' ')}`;
22	  return `usage: ${prog}${tail}\n`;
23	}
24	
25	export function formatHelp(prog, actions) {
26	  const invocations = actions.map(formatInvocation);
27	  const actionMaxLength = Math.max(0, ...invocations.map((text) => text.length + INDENT));
28	  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
29	  const actionWidth = helpPosition - INDENT - 2;
30	
31	  const pad = ' '.repeat(INDENT);
32	  const lines = [formatUsage(prog, actions), '\n', 'options:\n'];
33	
34	  actions.forEach((action, index) => {
35	    const invocation = invocations[index];
36	    if (!action.help) {
37	      // No help text: the invocation stands alone, with no trailing padding.
38	      lines.push(`${pad}${invocation}\n`);
39	    } else if (invocation.length <= actionWidth) {
40	      lines.push(`${pad}${invocation.padEnd(actionWidth)}  ${action.help}\n`);
41	    } else {
42	      // Too wide to share a line, so the help text starts on the next one.
43	      lines.push(`${pad}${invocation}\n`);
44	      lines.push(`${' '.repeat(helpPosition)}${action.help}\n`);
45	    }
46	  });
47	
48	  return `${lines.join('').replace(/\n+$/, '')}\n`;
49	}
