// Generates /tmp/corpus/argparse-forms.json: a JSON array of argv arrays that
// stress ONLY the command-line-parsing surface of test12 (argparse forms).
import { mkdirSync, writeFileSync } from 'node:fs';

const ADDR = 'bc1pqypqj3p230'; // hrp "bc" -> witver 1, [8, 128]
const HRP = 'bc';

const cases = [];
const seen = new Set();
const add = (...argv) => {
  const key = JSON.stringify(argv);
  if (!seen.has(key)) {
    seen.add(key);
    cases.push(argv);
  }
};

// ---------------------------------------------------------------- 1. baseline
add('--a', HRP, '--b', ADDR);
add('--b', ADDR, '--a', HRP);
add('--a=' + HRP, '--b=' + ADDR);
add('--b=' + ADDR, '--a=' + HRP);
add('--a=' + HRP, '--b', ADDR);
add('--a', HRP, '--b=' + ADDR);
add('--b', ADDR, '--a=' + HRP);
add('--b=' + ADDR, '--a', HRP);

// ------------------------------------------------- 2. missing required things
add();
add('--a', HRP);
add('--b', ADDR);
add('--a=' + HRP);
add('--b=' + ADDR);
add('--a');
add('--b');
add('--a', '--b');
add('--b', '--a');
add('--a=');
add('--b=');
add('--a=', '--b=');
add('--a', '', '--b', '');
add('--a', HRP, '--b');
add('--b', ADDR, '--a');
add('--a', HRP, '--b', ADDR, '--a');
add('--a', HRP, '--b', ADDR, '--b');
add('--a', '--b', ADDR);
add('--b', '--a', HRP);
add('--a=' + HRP, '--b');
add('--b=' + ADDR, '--a');

// -------------------------------------------------- 3. values containing '='
for (const v of ['=', '=x', 'x=', 'a=b', 'bc=x', '==', 'a=b=c', '=' + ADDR]) {
  add('--a=' + v, '--b', ADDR);
  add('--a', v, '--b', ADDR);
  add('--a', HRP, '--b=' + v);
  add('--a', HRP, '--b', v);
}

// ------------------------------------------------------ 4. repeated options
add('--a', 'tb', '--a', HRP, '--b', ADDR);
add('--a', HRP, '--a', 'tb', '--b', ADDR);
add('--a', HRP, '--b', 'zz', '--b', ADDR);
add('--a', HRP, '--b', ADDR, '--b', 'zz');
add('--a=tb', '--a=' + HRP, '--b', ADDR);
add('--a', 'x', '--a', 'y', '--a', HRP, '--b', ADDR);
add('--a', HRP, '--b', ADDR, '--a', HRP, '--b', ADDR);
